INSERT INTO cine.peliculas (id, tmdb_id, titulo, sinopsis, poster, fondo, trailer_url, foco_poster, foco_fondo, duracion, limpieza, estreno, distribuidora_id, idiomas_json, preventa, publicada, creado_utc) VALUES
(986056, 986056, 'Thunderbolts*', 'Un grupo de supervillanos poco convencional es reclutado para hacer misiones para el gobierno: Yelena Belova, Bucky Barnes, Red Guardian, Ghost, Taskmaster y John Walker. Después de verse atrapados en una trampa mortal urdida por Valentina Allegra de Fontaine, estos marginados deben embarcarse en una peligrosa misión que les obligará a enfrentarse a los recovecos más oscuros de su pasado.', '/images/peliculas/986056-poster.webp', '/images/peliculas/986056-fondo.webp', 'https://www.youtube.com/watch?v=WkGWtA8w_JY', 50, 35, 127, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -60), 1, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1234821, 1234821, 'Jurassic World: El renacer', 'Cinco años después de los eventos de "Dominion", la ecología del planeta ha demostrado ser insoportable para los dinosaurios, donde los pocos que quedan viven aislados en las regiones ecuatoriales. Zora Bennett es contratada para dirigir a un equipo de especialistas cuyo objetivo es conseguir el material genético de las tres criaturas más grandes, las cuales tienen en su ADN la clave para fabricar un medicamento que aportará grandes beneficios a la humanidad. Pero la operación se cruzará con una familia cuyo barco volcó y todos acabarán en una isla prohibida ocupada por dinosaurios de numerosas especies, donde tendrán que hacer lo imposible para sobrevivir.', '/images/peliculas/1234821-poster.webp', '/images/peliculas/1234821-fondo.webp', 'https://www.youtube.com/watch?v=N91J2N3uLgY', 50, 35, 133, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -61), 2, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(822119, 822119, 'Capitán América: Brave New World', 'Tras reunirse con el recién elegido presidente de los EE. UU., Thaddeus Ross, Sam se encuentra en medio de un incidente internacional. Debe descubrir el motivo que se esconde tras un perverso complot global, antes de que su verdadero artífice enfurezca al mundo entero.', '/images/peliculas/822119-poster.webp', '/images/peliculas/822119-fondo.webp', 'https://www.youtube.com/watch?v=vJ2Ppx5ZFvw', 50, 35, 119, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -62), 1, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(993710, 993710, 'De vuelta a la acción', 'Emily y Matt renunciaron hace años a ser espías de la CIA para formar una familia. Pero, cuando se descubre su tapadera, se ven arrastrados de nuevo al mundo del espionaje.', '/images/peliculas/993710-poster.webp', '/images/peliculas/993710-fondo.webp', '', 50, 35, 114, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -63), 3, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1426142, 1426142, 'Ricos, sin duda', 'Tras ser víctimas de una estafa que les deja una deuda millonaria, dos aspirantes a ingresar en la clase alta crean identidades falsas para timar a gente adinerada.', '/images/peliculas/1426142-poster.webp', '/images/peliculas/1426142-fondo.webp', '', 50, 35, 102, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -64), 3, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(696506, 696506, 'Mickey 17', 'Mickey 17, un miembro de la tripulación ''expendable'' (prescindible) enviado a un planeta helado para colonizarlo, se niega a dejar que su clon de reemplazo, Mickey 18, tome su lugar... Adaptación del libro original de Edward Ashton.', '/images/peliculas/696506-poster.webp', '/images/peliculas/696506-fondo.webp', 'https://www.youtube.com/watch?v=h_NsnK_6edE', 50, 35, 137, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -65), 4, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(661539, 661539, 'A Complete Unknown', 'Bob Dylan se hizo un nombre en el mundo del folk a muy temprana edad con sus versiones acústicas. Así que cuando en 1965, en el Newport Folk Festival, decidió conectar una guitarra eléctrica y usarla en su concierto, fue un duro golpe para los puristas del folk que veían el futuro del género en el joven. Desde ese momento, la vida de Dylan cambió profundamente. Siendo atacado por un gran grupo de seguidores del folk que lo tachaban de traidor, haciendo que su carrera no volviera a ser la misma. Ese concierto fue clave, se declaró como un músico independiente y fue el comienzo de la voz de una generación.', '/images/peliculas/661539-poster.webp', '/images/peliculas/661539-fondo.webp', 'https://www.youtube.com/watch?v=CVdbRstHgk4', 50, 35, 141, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -66), 5, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1241436, 1241436, 'Warfare. Tiempo de guerra', 'Basada en las experiencias reales del ex marine Ray Mendoza (codirector y coguionista de la película) durante la guerra de Irak. Introduce al espectador en la experiencia de un pelotón de Navy SEALs estadounidenses. Concretamente en una misión de vigilancia que se tuerce en territorio insurgente. Una historia visceral y a pie de campo sobre la guerra moderna y la hermandad, contada como nunca antes: en tiempo real y basada en los recuerdos de quienes la vivieron.', '/images/peliculas/1241436-poster.webp', '/images/peliculas/1241436-fondo.webp', '', 50, 35, 95, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -67), 6, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1423191, 1423191, 'Resident Evil: Noche cero', 'Un desafortunado mensajero, encargado de entregar un paquete a un hospital remoto, se ve atrapado en medio de un brote y debe luchar contra hordas de criaturas mutantes para sobrevivir.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1423191-poster-8f4ef99eafa7.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1423191-fondo-15241976cbab.webp', 'https://www.youtube.com/watch?v=8iKTeIV2xgE', 50, 35, 95, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -68), 4, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1100988, 1100988, '28 años después', 'Casi 30 años después de que el virus de la rabia asolara Inglaterra el joven Spike y su padre abandonan la seguridad de su fortaleza en una remota isla donde viven protegidos de los infectados, y emprenden un peligroso viaje de iniciación.', '/images/peliculas/1100988-poster.webp', '/images/peliculas/1100988-fondo.webp', 'https://www.youtube.com/watch?v=d-4F7jJUoOE', 50, 35, 115, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -69), 8, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1078605, 1078605, 'Weapons', 'Cuando todos los niños de una secundaria, menos uno, desaparecen misteriosamente la misma noche y exactamente a la misma hora, toda la comunidad de un pequeño pueblo se pregunta quién (o qué) es responsable de su desaparición.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1078605-poster-1e1e0e4b0189.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1078605-fondo-1f72f1e47a4e.webp', 'https://www.youtube.com/watch?v=aaca862hpnU', 50, 35, 129, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -70), 2, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1400837, 1400837, 'Madre siniestra', 'Bela, una niña de 8 años que vive en un hogar con problemas matrimoniales, enfrenta a una entidad siniestra que sale de su clóset. La presencia, a quien llama “Otra Mamá”, se vuelve cada vez más amenazante para ella y su familia.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1400837-poster-004ec8fd5f83.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1400837-fondo-00b81bda7ceb.webp', 'https://www.youtube.com/watch?v=gUrcl1APfVY', 50, 35, 93, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -71), 3, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(299534, 299534, 'Vengadores: Endgame', 'Tras el chasquido de Thanos que eliminó a la mitad de la vida en el universo, los Vengadores supervivientes quedan devastados y divididos. Cinco años después, una inesperada oportunidad les permite intentar revertir la catástrofe. Reuniéndose una vez más, los héroes emprenden una misión extrema que los obliga a viajar al pasado, enfrentarse a sus propias pérdidas y hacer sacrificios definitivos para restaurar el equilibrio del universo.', '/images/peliculas/299534-poster.webp', '/images/peliculas/299534-fondo.webp', '', 50, 35, 181, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -72), 1, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(24428, 24428, 'Vengadores', 'Cuando un enemigo inesperado surge como una gran amenaza para la seguridad mundial, Nick Fury, director de la Agencia SHIELD, decide reclutar a un equipo para salvar al mundo de un desastre casi seguro.', '/images/peliculas/24428-poster.webp', '/images/peliculas/24428-fondo.webp', '', 50, 35, 142, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -73), 1, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(194662, 194662, 'Birdman o la inesperada virtud de la ignorancia', 'Después de hacerse famoso interpretando a un célebre superhéroe, un actor trata de darle un nuevo rumbo a su vida, recuperando a su familia y preparándose para el estreno de una obra teatral en Broadway.', '/images/peliculas/194662-poster.webp', '/images/peliculas/194662-fondo.webp', '', 50, 35, 119, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -74), 5, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(569094, 569094, 'Spider-Man: Cruzando el Multiverso', 'Tras reencontrarse con Gwen Stacy, el amigable vecindario de Spider-Man de Brooklyn al completo es catapultado a través del Multiverso, donde se encuentra con un equipo de Spidermans encargados de proteger su propia existencia. Pero cuando los héroes se enfrentan sobre cómo manejar una nueva amenaza, Miles se encuentra enfrentado a las otras Arañas y debe redefinir lo que significa ser un héroe para poder salvar a la gente que más quiere.', '/images/peliculas/569094-poster.webp', '/images/peliculas/569094-fondo.webp', '', 50, 35, 140, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -75), 8, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(238, 238, 'El padrino', 'Don Vito Corleone, conocido dentro de los círculos del hampa como "El Padrino", es el patriarca de una de las cinco familias que ejercen el mando de la Cosa Nostra en Nueva York (Estados Unidos) durante la década de 1940. Don Corleone tiene cuatro hijos: una chica, Connie, y tres varones; Sonny, Michael y Fredo. Cuando Vito reclina intervenir en el negocio de estupefacientes, empieza una cruenta lucha de violentos episodios entre las distintas familias del crimen organizado.', '/images/peliculas/238-poster.webp', '/images/peliculas/238-fondo.webp', '', 50, 35, 175, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -76), 9, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(11216, 11216, 'Cinema Paradiso', 'En un pequeño pueblo siciliano durante los años previos a la llegada de la televisión (justo al finalizar la Segunda Guerra Mundial) el joven Toto vivía fascinado por el cine. Toto trata de entablar amistad con Alfredo, el proyeccionista del cine local, una persona muy irritable pero con un gran corazón. Todos estos hechos se presentan en forma de nostálgicos recuerdos de Toto que ha crecido hasta convertirse en un cineasta de éxito, y que revive a su infancia cuando recibe la noticia de que Alfredo ha muerto.', '/images/peliculas/11216-poster.webp', '/images/peliculas/11216-fondo.webp', '', 50, 35, 155, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -77), 10, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(13, 13, 'Forrest Gump', 'Forrest Gump es un chico con deficiencias mentales no muy profundas y con alguna incapacidad motora que, a pesar de todo, llegará a convertirse, entre otras cosas, en un héroe durante la Guerra del Vietnam. Su persistencia y bondad le llevarán a conseguir una gran fortuna, ser objeto del clamor popular y a codearse con las más altas esferas sociales y políticas del país. Siempre sin olvidar a Jenny, su gran amor desde que era niño.', '/images/peliculas/13-poster.webp', '/images/peliculas/13-fondo.webp', '', 50, 35, 142, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -78), 9, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(120, 120, 'El señor de los anillos: La comunidad del anillo', 'En la Tierra Media, el Señor Oscuro Saurón creó los Grandes Anillos de Poder, forjados por los herreros Elfos. Tres para los reyes Elfos, siete para los Señores Enanos, y nueve para los Hombres Mortales. Secretamente, Saurón también forjó un anillo maestro, el Anillo Único, que contiene en sí el poder para esclavizar a toda la Tierra Media. Con la ayuda de un grupo de amigos y de valientes aliados, Frodo emprende un peligroso viaje con la misión de destruir el Anillo Único. Pero el Señor Oscuro Sauron, quien creara el Anillo, envía a sus servidores para perseguir al grupo. Si Sauron lograra recuperar el Anillo, sería el final de la Tierra Media.', '/images/peliculas/120-poster.webp', '/images/peliculas/120-fondo.webp', '', 50, 35, 179, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + -79), 11, '["Español","Subtitulada"]', FALSE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1255833, 1255833, 'Whalefall', 'Tras la muerte de su padre, Jay Gardiner se sumerge en la costa central de California en busca de sus restos, pero es tragado por una ballena. Atrapado en su interior con solo una hora de oxígeno restante, Jay se da cuenta de que las lecciones que su padre le enseñó pueden ser la clave para escapar.', '/images/peliculas/1255833-poster.webp', '/images/peliculas/1255833-fondo.webp', '', 50, 35, 98, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 7), 12, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1003596, 1003596, 'Avengers: Doomsday', 'Héroes amados de tres universos distintos están en rumbo a una colisión letal y enfrentan una amenaza existencial como ninguna otra que hayan conocido.', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1003596-poster-1886d09e7ea7.webp', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1003596-fondo-863bad4a5a8c.webp', 'https://www.youtube.com/watch?v=lAr_uspgHm8', 50, 35, 165, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 21), 1, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1400940, 1400940, 'Clayface', 'Una criatura cambiante hecha de arcilla mágica acecha Ciudad Gótica, alternando entre villano y aliado de Batman. Varias figuras trágicas han asumido el manto de Cara de Barro a lo largo de los años.', '/images/peliculas/1400940-poster.webp', '/images/peliculas/1400940-fondo.webp', '', 50, 35, 108, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 10), 4, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1294189, 1294189, 'The Mongoose', 'Acusado de un delito que no cometió y sin nada que perder, un héroe de guerra llamado Ryan «Fang» Flanagan se enfrenta a las agresivas fuerzas del orden en una persecución en coche por todo el país, con la ayuda de sus compañeros de armas y de un público comprensivo que anima su huida.', '/images/peliculas/1294189-poster.webp', '/images/peliculas/1294189-fondo.webp', '', 50, 35, 99, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 14), 13, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1381071, 1381071, 'Godzilla Minus Zero', 'La guerra dejó a Japón en la ruina, y Godzilla lo sumió en una situación aún peor. Han pasado dos años desde entonces, y el país ha librado una lucha ardua por recuperarse y finalmente retomar su vida cotidiana. Justo cuando la humanidad lograba aferrarse a una paz duramente conquistada, una nueva amenaza irrumpe, aplastando la esperanza en un instante.', '/images/peliculas/1381071-poster.webp', '/images/peliculas/1381071-fondo.webp', '', 50, 35, 135, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 18), 14, '["Español","Subtitulada"]', TRUE, TRUE, (CURRENT_TIMESTAMP - interval '49 days')),
(1170608, 1170608, 'Dune: Parte tres', 'Paul Atreides, ahora Emperador Muad''Dib, se desenvuelve en su inmenso poder mientras lucha contra enemigos políticos y una conspiración dentro de su círculo. Mientras la Casa Atreides se enfrenta al colapso, surge el verdadero peligro para la amante de Paul, Chani, y su heredero nonato.', '/images/estrenos/1170608.webp', '/images/estrenos/1170608.webp', '', 50, 35, 165, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 25), 4, '["Doblada","Subtitulada"]', TRUE, TRUE, CURRENT_TIMESTAMP - interval '15 days'),
(1297467, 1297467, 'The Exorcist: Martyrs', '', '/images/estrenos/1297467.webp', '/images/estrenos/1297467.webp', '', 50, 35, 120, 20, ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 28), 2, '["Doblada","Subtitulada"]', TRUE, TRUE, CURRENT_TIMESTAMP - interval '15 days');
