INSERT INTO cine.estrenos (id, titulo, imagen, genero, fecha, sinopsis, publicado, pelicula_id) VALUES
(1255833, 'Whalefall', '/images/estrenos/1255833.webp', 'Suspenso', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 7), 'Tras la muerte de su padre, Jay Gardiner se sumerge en la costa central de California en busca de sus restos, pero es tragado por una ballena. Atrapado en su interior con solo una hora de oxígeno restante, Jay se da cuenta de que las lecciones que su padre le enseñó pueden ser la clave para escapar.', TRUE, 1255833),
(1400940, 'Clayface', '/images/estrenos/1400940.webp', 'Terror', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 10), 'Una criatura cambiante hecha de arcilla mágica acecha Ciudad Gótica, alternando entre villano y aliado de Batman. Varias figuras trágicas han asumido el manto de Cara de Barro a lo largo de los años.', TRUE, 1400940),
(1294189, 'The Mongoose', '/images/estrenos/1294189.webp', 'Acción', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 14), 'Acusado de un delito que no cometió y sin nada que perder, un héroe de guerra llamado Ryan «Fang» Flanagan se enfrenta a las agresivas fuerzas del orden en una persecución en coche por todo el país, con la ayuda de sus compañeros de armas y de un público comprensivo que anima su huida.', TRUE, 1294189),
(1381071, 'Godzilla Minus Zero', '/images/estrenos/1381071.webp', 'Ciencia ficción', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 18), 'La guerra dejó a Japón en la ruina, y Godzilla lo sumió en una situación aún peor. Han pasado dos años desde entonces, y el país ha librado una lucha ardua por recuperarse y finalmente retomar su vida cotidiana. Justo cuando la humanidad lograba aferrarse a una paz duramente conquistada, una nueva amenaza irrumpe, aplastando la esperanza en un instante.', TRUE, 1381071),
(1170608, 'Dune: Parte tres', '/images/estrenos/1170608.webp', 'Ciencia ficción', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 25), 'Paul Atreides, ahora Emperador Muad''Dib, se desenvuelve en su inmenso poder mientras lucha contra enemigos políticos y una conspiración dentro de su círculo. Mientras la Casa Atreides se enfrenta al colapso, surge el verdadero peligro para la amante de Paul, Chani, y su heredero nonato.', TRUE, 1170608),
(1003596, 'Vengadores: Doomsday', 'https://beopqvzyjrqtcersuhcu.supabase.co/storage/v1/object/public/cinespace-media/peliculas/seed/1003596-poster-1886d09e7ea7.webp', 'Ciencia ficción', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 21), 'Quinta entrega de la saga ''Vengadores'' incluida en el Universo Cinematográfico Marvel (UCM). Sinopsis desconocido.', TRUE, 1003596),
(1297467, 'The Exorcist: Martyrs', '/images/estrenos/1297467.webp', 'Terror', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 28), '', TRUE, 1297467),
(1765072, 'You Can See Everything', '/images/estrenos/1765072.webp', 'Documental', ((CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date + 35), 'Una mirada documental a historias que merecen ser descubiertas en la pantalla grande.', TRUE, NULL);
