-- CineSpace: reconstruccion manual, consolidada y transaccional.
-- Ejecutar exclusivamente mediante update_DB.bat por el propietario.
-- Elimina solamente el esquema cine; conserva auth, storage y sus objetos.
-- Los usuarios de prueba se crean con hashes PBKDF2 de ASP.NET Core Identity.
BEGIN;
DROP SCHEMA IF EXISTS cine CASCADE;
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions;
-- 1. ESTRUCTURA, RELACIONES E INDICES

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'cine') THEN
        CREATE SCHEMA cine;
    END IF;
END $EF$;


CREATE TABLE cine.ajustes (
    clave text NOT NULL,
    valor text NOT NULL,
    CONSTRAINT "PK_ajustes" PRIMARY KEY (clave)
);


CREATE TABLE cine.categorias (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre character varying(200) NOT NULL,
    descripcion text NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_categorias" PRIMARY KEY (id)
);


CREATE TABLE cine.claves_proteccion (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    friendly_name text,
    xml text,
    CONSTRAINT "PK_claves_proteccion" PRIMARY KEY (id)
);


CREATE TABLE cine.disenos (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    filas integer NOT NULL,
    columnas integer NOT NULL,
    plano_json jsonb NOT NULL,
    nombre character varying(200) NOT NULL,
    descripcion text NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_disenos" PRIMARY KEY (id)
);


CREATE TABLE cine.distribuidoras (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    contacto text NOT NULL,
    email text NOT NULL,
    telefono text NOT NULL,
    nombre character varying(200) NOT NULL,
    descripcion text NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_distribuidoras" PRIMARY KEY (id)
);


CREATE TABLE cine.estrenos (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    pelicula_id integer,
    titulo text NOT NULL,
    imagen text NOT NULL,
    genero text NOT NULL,
    fecha date NOT NULL,
    sinopsis text NOT NULL,
    publicado boolean NOT NULL,
    CONSTRAINT "PK_estrenos" PRIMARY KEY (id)
);


CREATE TABLE cine.experiencias (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre character varying(200) NOT NULL,
    descripcion text NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_experiencias" PRIMARY KEY (id)
);


CREATE TABLE cine.generos (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre character varying(200) NOT NULL,
    descripcion text NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_generos" PRIMARY KEY (id)
);


CREATE TABLE cine.roles (
    id uuid NOT NULL,
    name character varying(256),
    normalized_name character varying(256),
    concurrency_stamp text,
    CONSTRAINT "PK_roles" PRIMARY KEY (id)
);


CREATE TABLE cine.tipos_sala (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre character varying(200) NOT NULL,
    descripcion text NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_tipos_sala" PRIMARY KEY (id)
);


CREATE TABLE cine.usuarios (
    id uuid NOT NULL,
    nombre character varying(100) NOT NULL,
    apellido character varying(100) NOT NULL,
    ci character varying(30),
    activo boolean NOT NULL,
    fecha_registro_utc timestamp with time zone NOT NULL,
    user_name character varying(256),
    normalized_user_name character varying(256),
    email character varying(256),
    normalized_email character varying(256),
    email_confirmed boolean NOT NULL,
    password_hash text,
    security_stamp text,
    concurrency_stamp text,
    phone_number text,
    phone_number_confirmed boolean NOT NULL,
    two_factor_enabled boolean NOT NULL,
    lockout_end timestamp with time zone,
    lockout_enabled boolean NOT NULL,
    access_failed_count integer NOT NULL,
    CONSTRAINT "PK_usuarios" PRIMARY KEY (id)
);


CREATE TABLE cine.combos (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    categoria_id integer NOT NULL,
    precio numeric(12,2) NOT NULL,
    foto text NOT NULL,
    publicado boolean NOT NULL,
    nombre character varying(200) NOT NULL,
    descripcion text NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_combos" PRIMARY KEY (id),
    CONSTRAINT "FK_combos_categorias_categoria_id" FOREIGN KEY (categoria_id) REFERENCES cine.categorias (id) ON DELETE RESTRICT
);


CREATE TABLE cine.peliculas (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    tmdb_id integer,
    titulo text NOT NULL,
    sinopsis text NOT NULL,
    poster text NOT NULL,
    fondo text NOT NULL,
    trailer_url text NOT NULL,
    foco_poster integer NOT NULL,
    foco_fondo integer NOT NULL,
    duracion integer NOT NULL,
    limpieza integer NOT NULL,
    estreno date,
    distribuidora_id integer,
    idiomas_json jsonb NOT NULL,
    preventa boolean NOT NULL,
    publicada boolean NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_peliculas" PRIMARY KEY (id),
    CONSTRAINT "FK_peliculas_distribuidoras_distribuidora_id" FOREIGN KEY (distribuidora_id) REFERENCES cine.distribuidoras (id) ON DELETE RESTRICT
);


ALTER TABLE cine.estrenos ADD CONSTRAINT "FK_estrenos_peliculas_pelicula_id" FOREIGN KEY (pelicula_id) REFERENCES cine.peliculas (id) ON DELETE RESTRICT;

CREATE TABLE cine.roles_claims (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    role_id uuid NOT NULL,
    claim_type text,
    claim_value text,
    CONSTRAINT "PK_roles_claims" PRIMARY KEY (id),
    CONSTRAINT "FK_roles_claims_roles_role_id" FOREIGN KEY (role_id) REFERENCES cine.roles (id) ON DELETE CASCADE
);


CREATE TABLE cine.salas (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    nombre text NOT NULL,
    diseno_id integer NOT NULL,
    tipo_sala_id integer NOT NULL,
    precio numeric(12,2) NOT NULL,
    descuento integer NOT NULL,
    activa boolean NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_salas" PRIMARY KEY (id),
    CONSTRAINT "FK_salas_disenos_diseno_id" FOREIGN KEY (diseno_id) REFERENCES cine.disenos (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_salas_tipos_sala_tipo_sala_id" FOREIGN KEY (tipo_sala_id) REFERENCES cine.tipos_sala (id) ON DELETE RESTRICT
);


CREATE TABLE cine.pedidos (
    id uuid NOT NULL,
    numero text NOT NULL,
    token text NOT NULL,
    solicitud text NOT NULL,
    codigo text NOT NULL,
    usuario_id uuid,
    propietario_invitado text NOT NULL,
    nombre_retiro text NOT NULL,
    estado text NOT NULL,
    metodo_pago text NOT NULL,
    total numeric(12,2) NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    retirado_utc timestamp with time zone,
    entregado_por_id uuid,
    CONSTRAINT "PK_pedidos" PRIMARY KEY (id),
    CONSTRAINT "FK_pedidos_usuarios_entregado_por_id" FOREIGN KEY (entregado_por_id) REFERENCES cine.usuarios (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_pedidos_usuarios_usuario_id" FOREIGN KEY (usuario_id) REFERENCES cine.usuarios (id) ON DELETE RESTRICT
);


CREATE TABLE cine.trabajadores (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    usuario_id uuid NOT NULL,
    nacimiento date NOT NULL,
    telefono text NOT NULL,
    direccion text NOT NULL,
    nacionalidad text NOT NULL,
    cargo integer NOT NULL,
    horario text NOT NULL,
    sueldo numeric(12,2) NOT NULL,
    CONSTRAINT "PK_trabajadores" PRIMARY KEY (id),
    CONSTRAINT "FK_trabajadores_usuarios_usuario_id" FOREIGN KEY (usuario_id) REFERENCES cine.usuarios (id) ON DELETE RESTRICT
);


CREATE TABLE cine.usuarios_claims (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    user_id uuid NOT NULL,
    claim_type text,
    claim_value text,
    CONSTRAINT "PK_usuarios_claims" PRIMARY KEY (id),
    CONSTRAINT "FK_usuarios_claims_usuarios_user_id" FOREIGN KEY (user_id) REFERENCES cine.usuarios (id) ON DELETE CASCADE
);


CREATE TABLE cine.usuarios_logins (
    login_provider text NOT NULL,
    provider_key text NOT NULL,
    provider_display_name text,
    user_id uuid NOT NULL,
    CONSTRAINT "PK_usuarios_logins" PRIMARY KEY (login_provider, provider_key),
    CONSTRAINT "FK_usuarios_logins_usuarios_user_id" FOREIGN KEY (user_id) REFERENCES cine.usuarios (id) ON DELETE CASCADE
);


CREATE TABLE cine.usuarios_roles (
    user_id uuid NOT NULL,
    role_id uuid NOT NULL,
    CONSTRAINT "PK_usuarios_roles" PRIMARY KEY (user_id, role_id),
    CONSTRAINT "FK_usuarios_roles_roles_role_id" FOREIGN KEY (role_id) REFERENCES cine.roles (id) ON DELETE CASCADE,
    CONSTRAINT "FK_usuarios_roles_usuarios_user_id" FOREIGN KEY (user_id) REFERENCES cine.usuarios (id) ON DELETE CASCADE
);


CREATE TABLE cine.usuarios_tokens (
    user_id uuid NOT NULL,
    login_provider text NOT NULL,
    name text NOT NULL,
    value text,
    CONSTRAINT "PK_usuarios_tokens" PRIMARY KEY (user_id, login_provider, name),
    CONSTRAINT "FK_usuarios_tokens_usuarios_user_id" FOREIGN KEY (user_id) REFERENCES cine.usuarios (id) ON DELETE CASCADE
);


CREATE TABLE cine.banners (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    pelicula_id integer NOT NULL,
    imagen text NOT NULL,
    etiqueta integer NOT NULL,
    foco integer NOT NULL,
    orden integer NOT NULL,
    activo boolean NOT NULL,
    CONSTRAINT "PK_banners" PRIMARY KEY (id),
    CONSTRAINT "FK_banners_peliculas_pelicula_id" FOREIGN KEY (pelicula_id) REFERENCES cine.peliculas (id) ON DELETE RESTRICT
);


CREATE TABLE cine.peliculas_generos (
    pelicula_id integer NOT NULL,
    genero_id integer NOT NULL,
    CONSTRAINT "PK_peliculas_generos" PRIMARY KEY (pelicula_id, genero_id),
    CONSTRAINT "FK_peliculas_generos_generos_genero_id" FOREIGN KEY (genero_id) REFERENCES cine.generos (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_peliculas_generos_peliculas_pelicula_id" FOREIGN KEY (pelicula_id) REFERENCES cine.peliculas (id) ON DELETE CASCADE
);


CREATE TABLE cine.resenas (
    id uuid NOT NULL,
    destacada boolean NOT NULL,
    pelicula_id integer NOT NULL,
    usuario_id uuid NOT NULL,
    puntuacion integer NOT NULL,
    comentario text NOT NULL,
    fecha_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_resenas" PRIMARY KEY (id),
    CONSTRAINT "FK_resenas_peliculas_pelicula_id" FOREIGN KEY (pelicula_id) REFERENCES cine.peliculas (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_resenas_usuarios_usuario_id" FOREIGN KEY (usuario_id) REFERENCES cine.usuarios (id) ON DELETE RESTRICT
);


CREATE TABLE cine.salas_experiencias (
    sala_id integer NOT NULL,
    experiencia_id integer NOT NULL,
    CONSTRAINT "PK_salas_experiencias" PRIMARY KEY (sala_id, experiencia_id),
    CONSTRAINT "FK_salas_experiencias_experiencias_experiencia_id" FOREIGN KEY (experiencia_id) REFERENCES cine.experiencias (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_salas_experiencias_salas_sala_id" FOREIGN KEY (sala_id) REFERENCES cine.salas (id) ON DELETE CASCADE
);


CREATE TABLE cine.pedido_lineas (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    pedido_id uuid NOT NULL,
    combo_id integer NOT NULL,
    nombre text NOT NULL,
    categoria text NOT NULL,
    cantidad integer NOT NULL,
    precio_unitario numeric(12,2) NOT NULL,
    CONSTRAINT "PK_pedido_lineas" PRIMARY KEY (id),
    CONSTRAINT "FK_pedido_lineas_combos_combo_id" FOREIGN KEY (combo_id) REFERENCES cine.combos (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_pedido_lineas_pedidos_pedido_id" FOREIGN KEY (pedido_id) REFERENCES cine.pedidos (id) ON DELETE CASCADE
);


CREATE TABLE cine.programaciones (
    id uuid NOT NULL,
    pelicula_id integer NOT NULL,
    sala_id integer NOT NULL,
    experiencia_id integer NOT NULL,
    desde date NOT NULL,
    hasta date NOT NULL,
    horario_json jsonb NOT NULL,
    creado_utc timestamp with time zone NOT NULL,
    CONSTRAINT "PK_programaciones" PRIMARY KEY (id),
    CONSTRAINT "FK_programaciones_experiencias_experiencia_id" FOREIGN KEY (experiencia_id) REFERENCES cine.experiencias (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_programaciones_peliculas_pelicula_id" FOREIGN KEY (pelicula_id) REFERENCES cine.peliculas (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_programaciones_salas_experiencias_sala_id_experiencia_id" FOREIGN KEY (sala_id, experiencia_id) REFERENCES cine.salas_experiencias (sala_id, experiencia_id) ON DELETE RESTRICT,
    CONSTRAINT "FK_programaciones_salas_sala_id" FOREIGN KEY (sala_id) REFERENCES cine.salas (id) ON DELETE RESTRICT
);


CREATE TABLE cine.funciones (
    id uuid NOT NULL,
    programacion_id uuid NOT NULL,
    pelicula_id integer NOT NULL,
    sala_id integer NOT NULL,
    experiencia_id integer NOT NULL,
    inicio_utc timestamp with time zone NOT NULL,
    sala_lista_utc timestamp with time zone NOT NULL,
    duracion integer NOT NULL,
    limpieza integer NOT NULL,
    preventa boolean NOT NULL,
    CONSTRAINT "PK_funciones" PRIMARY KEY (id),
    CONSTRAINT "FK_funciones_experiencias_experiencia_id" FOREIGN KEY (experiencia_id) REFERENCES cine.experiencias (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_funciones_peliculas_pelicula_id" FOREIGN KEY (pelicula_id) REFERENCES cine.peliculas (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_funciones_programaciones_programacion_id" FOREIGN KEY (programacion_id) REFERENCES cine.programaciones (id) ON DELETE CASCADE,
    CONSTRAINT "FK_funciones_salas_experiencias_sala_id_experiencia_id" FOREIGN KEY (sala_id, experiencia_id) REFERENCES cine.salas_experiencias (sala_id, experiencia_id) ON DELETE RESTRICT,
    CONSTRAINT "FK_funciones_salas_sala_id" FOREIGN KEY (sala_id) REFERENCES cine.salas (id) ON DELETE RESTRICT
);


CREATE TABLE cine.ventas (
    id uuid NOT NULL,
    numero_factura text NOT NULL,
    codigo text NOT NULL,
    usuario_id uuid NOT NULL,
    operador_id uuid,
    funcion_id uuid NOT NULL,
    solicitud text NOT NULL,
    total numeric(12,2) NOT NULL,
    cantidad integer NOT NULL,
    metodo_pago text NOT NULL,
    fecha_utc timestamp with time zone NOT NULL,
    verificada_utc timestamp with time zone,
    snapshot_json jsonb NOT NULL,
    CONSTRAINT "PK_ventas" PRIMARY KEY (id),
    CONSTRAINT "FK_ventas_funciones_funcion_id" FOREIGN KEY (funcion_id) REFERENCES cine.funciones (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_ventas_usuarios_usuario_id" FOREIGN KEY (usuario_id) REFERENCES cine.usuarios (id) ON DELETE RESTRICT
);


CREATE TABLE cine.butacas_vendidas (
    funcion_id uuid NOT NULL,
    asiento text NOT NULL,
    venta_id uuid NOT NULL,
    CONSTRAINT "PK_butacas_vendidas" PRIMARY KEY (funcion_id, asiento),
    CONSTRAINT "FK_butacas_vendidas_funciones_funcion_id" FOREIGN KEY (funcion_id) REFERENCES cine.funciones (id) ON DELETE RESTRICT,
    CONSTRAINT "FK_butacas_vendidas_ventas_venta_id" FOREIGN KEY (venta_id) REFERENCES cine.ventas (id) ON DELETE RESTRICT
);


CREATE INDEX "IX_banners_pelicula_id" ON cine.banners (pelicula_id);


CREATE INDEX "IX_butacas_vendidas_venta_id" ON cine.butacas_vendidas (venta_id);


CREATE UNIQUE INDEX "IX_categorias_nombre" ON cine.categorias (nombre);


CREATE INDEX "IX_combos_categoria_id" ON cine.combos (categoria_id);


CREATE UNIQUE INDEX "IX_combos_nombre" ON cine.combos (nombre);


CREATE UNIQUE INDEX "IX_disenos_nombre" ON cine.disenos (nombre);


CREATE UNIQUE INDEX "IX_distribuidoras_nombre" ON cine.distribuidoras (nombre);


CREATE UNIQUE INDEX "IX_estrenos_pelicula_id" ON cine.estrenos (pelicula_id);

CREATE UNIQUE INDEX "IX_estrenos_titulo_fecha" ON cine.estrenos (titulo, fecha);


CREATE UNIQUE INDEX "IX_experiencias_nombre" ON cine.experiencias (nombre);


CREATE INDEX "IX_funciones_experiencia_id" ON cine.funciones (experiencia_id);


CREATE INDEX "IX_funciones_pelicula_id_inicio_utc" ON cine.funciones (pelicula_id, inicio_utc);


CREATE INDEX "IX_funciones_programacion_id" ON cine.funciones (programacion_id);


CREATE INDEX "IX_funciones_sala_id_experiencia_id" ON cine.funciones (sala_id, experiencia_id);


CREATE UNIQUE INDEX "IX_funciones_sala_id_inicio_utc" ON cine.funciones (sala_id, inicio_utc);


CREATE UNIQUE INDEX "IX_generos_nombre" ON cine.generos (nombre);


CREATE INDEX "IX_pedido_lineas_combo_id" ON cine.pedido_lineas (combo_id);


CREATE INDEX "IX_pedido_lineas_pedido_id" ON cine.pedido_lineas (pedido_id);


CREATE INDEX "IX_pedidos_entregado_por_id" ON cine.pedidos (entregado_por_id);


CREATE INDEX "IX_pedidos_estado_creado_utc" ON cine.pedidos (estado, creado_utc);


CREATE UNIQUE INDEX "IX_pedidos_numero" ON cine.pedidos (numero);


CREATE UNIQUE INDEX "IX_pedidos_solicitud" ON cine.pedidos (solicitud);


CREATE UNIQUE INDEX "IX_pedidos_token" ON cine.pedidos (token);


CREATE INDEX "IX_pedidos_usuario_id" ON cine.pedidos (usuario_id);


CREATE INDEX "IX_peliculas_creado_utc" ON cine.peliculas (creado_utc);


CREATE INDEX "IX_peliculas_distribuidora_id" ON cine.peliculas (distribuidora_id);


CREATE UNIQUE INDEX "IX_peliculas_tmdb_id" ON cine.peliculas (tmdb_id);


CREATE INDEX "IX_peliculas_generos_genero_id" ON cine.peliculas_generos (genero_id);


CREATE INDEX "IX_programaciones_experiencia_id" ON cine.programaciones (experiencia_id);


CREATE INDEX "IX_programaciones_pelicula_id" ON cine.programaciones (pelicula_id);


CREATE INDEX "IX_programaciones_sala_id_experiencia_id" ON cine.programaciones (sala_id, experiencia_id);


CREATE INDEX "IX_resenas_pelicula_id" ON cine.resenas (pelicula_id);


CREATE UNIQUE INDEX "IX_resenas_usuario_id_pelicula_id" ON cine.resenas (usuario_id, pelicula_id);


CREATE UNIQUE INDEX "RoleNameIndex" ON cine.roles (normalized_name);


CREATE INDEX "IX_roles_claims_role_id" ON cine.roles_claims (role_id);


CREATE INDEX "IX_salas_diseno_id" ON cine.salas (diseno_id);


CREATE UNIQUE INDEX "IX_salas_nombre" ON cine.salas (nombre);


CREATE INDEX "IX_salas_tipo_sala_id" ON cine.salas (tipo_sala_id);


CREATE INDEX "IX_salas_experiencias_experiencia_id" ON cine.salas_experiencias (experiencia_id);


CREATE UNIQUE INDEX "IX_tipos_sala_nombre" ON cine.tipos_sala (nombre);


CREATE UNIQUE INDEX "IX_trabajadores_usuario_id" ON cine.trabajadores (usuario_id);


CREATE UNIQUE INDEX "EmailIndex" ON cine.usuarios (normalized_email);


CREATE UNIQUE INDEX "IX_usuarios_ci" ON cine.usuarios (ci) WHERE ci IS NOT NULL AND ci <> '';


CREATE UNIQUE INDEX "UserNameIndex" ON cine.usuarios (normalized_user_name);


CREATE INDEX "IX_usuarios_claims_user_id" ON cine.usuarios_claims (user_id);


CREATE INDEX "IX_usuarios_logins_user_id" ON cine.usuarios_logins (user_id);


CREATE INDEX "IX_usuarios_roles_role_id" ON cine.usuarios_roles (role_id);


CREATE UNIQUE INDEX "IX_ventas_codigo" ON cine.ventas (codigo);


CREATE INDEX "IX_ventas_funcion_id" ON cine.ventas (funcion_id);


CREATE UNIQUE INDEX "IX_ventas_numero_factura" ON cine.ventas (numero_factura);


CREATE UNIQUE INDEX "IX_ventas_usuario_id_solicitud" ON cine.ventas (usuario_id, solicitud);




ALTER TABLE cine.salas ADD CONSTRAINT sala_precio_valido CHECK(precio > 0 AND precio <= 10000 AND descuento BETWEEN 0 AND 90);
ALTER TABLE cine.combos ADD CONSTRAINT combo_precio_valido CHECK(precio > 0 AND precio <= 10000);
ALTER TABLE cine.resenas ADD CONSTRAINT puntuacion_valida CHECK(puntuacion BETWEEN 1 AND 5 AND length(comentario) <= 4000);
ALTER TABLE cine.ventas ADD CONSTRAINT venta_valida CHECK(cantidad BETWEEN 1 AND 10000 AND total > 0);
ALTER TABLE cine.pedido_lineas ADD CONSTRAINT linea_valida CHECK(cantidad BETWEEN 1 AND 20 AND precio_unitario > 0);
ALTER TABLE cine.disenos ADD CONSTRAINT matriz_valida CHECK(filas BETWEEN 1 AND 100 AND columnas BETWEEN 1 AND 100);
ALTER TABLE cine.funciones ADD CONSTRAINT funcion_valida CHECK(duracion BETWEEN 1 AND 720 AND limpieza BETWEEN 0 AND 360 AND sala_lista_utc > inicio_utc);
ALTER TABLE cine.programaciones ADD CONSTRAINT periodo_valido CHECK(hasta >= desde AND hasta - desde <= 90);
ALTER TABLE cine.trabajadores ADD CONSTRAINT trabajador_valido CHECK(sueldo > 0 AND cargo BETWEEN 0 AND 5);
ALTER TABLE cine.pedidos ADD CONSTRAINT estado_pedido_valido CHECK(estado IN ('Pendiente','Retirado','Cancelado'));
CREATE INDEX peliculas_titulo_busqueda ON cine.peliculas USING gin(titulo extensions.gin_trgm_ops);
CREATE INDEX usuarios_registro_orden ON cine.usuarios(fecha_registro_utc DESC,id);
CREATE INDEX usuarios_rol_cuenta ON cine.usuarios_roles(role_id,user_id);
CREATE INDEX usuarios_email_busqueda ON cine.usuarios USING gin(email extensions.gin_trgm_ops);
CREATE INDEX usuarios_nombre_busqueda ON cine.usuarios USING gin((nombre || ' ' || apellido) extensions.gin_trgm_ops);
CREATE INDEX usuarios_ci_busqueda ON cine.usuarios USING gin(ci extensions.gin_trgm_ops);
CREATE INDEX combos_nombre_busqueda ON cine.combos USING gin(nombre extensions.gin_trgm_ops);
CREATE INDEX ventas_usuario_fecha ON cine.ventas(usuario_id, fecha_utc DESC, id);
CREATE INDEX ventas_fecha ON cine.ventas(fecha_utc DESC, id);
CREATE INDEX resenas_usuario_fecha ON cine.resenas(usuario_id, fecha_utc DESC, id);
CREATE INDEX pedidos_usuario_fecha ON cine.pedidos(usuario_id, creado_utc DESC, id);
CREATE INDEX pedidos_invitado_fecha ON cine.pedidos(propietario_invitado, creado_utc DESC) WHERE usuario_id IS NULL;
CREATE INDEX pedidos_estado_fecha ON cine.pedidos(estado, creado_utc DESC);
CREATE INDEX funciones_pelicula_fecha ON cine.funciones(pelicula_id, inicio_utc, sala_id);
CREATE INDEX funciones_sala_periodo ON cine.funciones(sala_id, inicio_utc, sala_lista_utc);
ALTER TABLE cine.ventas ADD CONSTRAINT venta_funcion_unica UNIQUE(id,funcion_id);
ALTER TABLE cine.butacas_vendidas ADD CONSTRAINT butaca_venta_funcion_coherente FOREIGN KEY(venta_id,funcion_id) REFERENCES cine.ventas(id,funcion_id);
CREATE OR REPLACE FUNCTION cine.validar_butaca() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM cine.funciones f JOIN cine.salas s ON s.id=f.sala_id JOIN cine.disenos d ON d.id=s.diseno_id WHERE f.id=NEW.funcion_id AND (d.plano_json->'asientos') ? NEW.asiento) THEN
  RAISE EXCEPTION 'La butaca no pertenece a la sala' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER butaca_del_plano BEFORE INSERT OR UPDATE ON cine.butacas_vendidas FOR EACH ROW EXECUTE FUNCTION cine.validar_butaca();
CREATE OR REPLACE FUNCTION cine.validar_solapamiento() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(NEW.sala_id);
 IF EXISTS (SELECT 1 FROM cine.funciones f WHERE f.sala_id=NEW.sala_id AND f.id<>NEW.id
   AND f.inicio_utc<NEW.sala_lista_utc AND f.sala_lista_utc>NEW.inicio_utc) THEN
  RAISE EXCEPTION 'Las funciones de la sala se solapan' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER funciones_sin_solapamiento BEFORE INSERT OR UPDATE ON cine.funciones FOR EACH ROW EXECUTE FUNCTION cine.validar_solapamiento();
-- 2. DATOS DE PRUEBA: catalogos y cuentas; despues programacion e historico.

















-- Mantener duración y limpieza alineadas con la ficha utilizada por el histórico.
UPDATE cine.programaciones pr SET horario_json=jsonb_set(jsonb_set(pr.horario_json,'{duracionMinutos}',to_jsonb(p.duracion)),'{limpiezaMinutos}',to_jsonb(p.limpieza)) FROM cine.peliculas p WHERE p.id=pr.pelicula_id;

-- Funciones relativas al dia de ejecución, generadas desde cada programación.
SELECT md5('seed-funcion:'||pr.id::text||':'||(dia::date-(CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date)::text||':'||hora)::uuid,
 pr.id,pr.pelicula_id,pr.sala_id,pr.experiencia_id,
 (dia::date+hora::time) AT TIME ZONE 'America/La_Paz',
 ((dia::date+hora::time) AT TIME ZONE 'America/La_Paz')+make_interval(mins=>p.duracion+p.limpieza),p.duracion,p.limpieza,p.preventa
FROM cine.programaciones pr JOIN cine.peliculas p ON p.id=pr.pelicula_id
CROSS JOIN LATERAL generate_series(pr.desde::timestamp,pr.hasta::timestamp,interval '1 day') dia
CROSS JOIN LATERAL jsonb_array_elements_text(pr.horario_json->'horarios') hora;












-- Actividad de prueba para hoy y los últimos 30 días, con importes y asientos reales.
WITH candidatas AS (
 SELECT f.*,s.precio,s.descuento,s.tipo_sala_id,d.plano_json,
   (f.inicio_utc AT TIME ZONE 'America/La_Paz')::date-(CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date AS dia
 FROM cine.funciones f JOIN cine.salas s ON s.id=f.sala_id JOIN cine.disenos d ON d.id=s.diseno_id
 WHERE NOT f.preventa AND (f.inicio_utc AT TIME ZONE 'America/La_Paz')::time='10:00'
   AND (f.inicio_utc AT TIME ZONE 'America/La_Paz')::date BETWEEN (CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date-30 AND (CURRENT_TIMESTAMP AT TIME ZONE 'America/La_Paz')::date
), nuevas AS (
 SELECT c.*,a.asientos FROM candidatas c
 CROSS JOIN LATERAL (SELECT jsonb_agg(asiento) asientos FROM (SELECT asiento FROM jsonb_array_elements_text(c.plano_json->'asientos') AS libre(asiento)
   WHERE NOT EXISTS(SELECT 1 FROM cine.butacas_vendidas b WHERE b.funcion_id=c.id AND b.asiento=libre.asiento) ORDER BY asiento LIMIT 2) libres) a
 WHERE (abs(c.dia)+c.sala_id)%3=0 AND jsonb_array_length(a.asientos)=2
)
SELECT md5('seed-venta:'||n.id)::uuid,'F-SEED-'||upper(substr(md5(n.id::text),1,12)),upper(substr(md5('boleto:'||n.id),1,12)),u.id,NULL,n.id,'seed-'||n.id,
 round(n.precio*(100-n.descuento)/100,2)*2,2,CASE WHEN n.sala_id%2=0 THEN 'Pago QR' ELSE 'Tarjeta de débito' END,
 least(CURRENT_TIMESTAMP,n.inicio_utc-interval '1 hour'),
 jsonb_build_object('peliculaId',n.pelicula_id,'pelicula',p.titulo,'numeroSala',n.sala_id,'tipoSala',n.tipo_sala_id,'tipoExperiencia',n.experiencia_id,
 'horario','10:00','fechaFuncion',to_char(n.inicio_utc AT TIME ZONE 'America/La_Paz','YYYY-MM-DD"T"HH24:MI:SS'),
 'ticketsMayores',2,'ticketsMenores',0,'asientos',n.asientos,'cliente',u.nombre||' '||u.apellido,'documentoCliente',u.ci,'emailUsuario',u.email,
 'asientosMayoresPorCategoria',jsonb_build_object('0',2),'preciosMayoresPorCategoria',jsonb_build_object('0',round(n.precio*(100-n.descuento)/100,2)))
FROM nuevas n JOIN cine.peliculas p ON p.id=n.pelicula_id
CROSS JOIN LATERAL (SELECT usr.* FROM cine.usuarios usr JOIN cine.usuarios_roles ur ON ur.user_id=usr.id JOIN cine.roles r ON r.id=ur.role_id WHERE r.name='Cliente'
 ORDER BY CASE WHEN usr.email='cliente@cliente.com' THEN 0 ELSE 1 END,usr.id LIMIT 1) u;
 SELECT v.funcion_id,a,v.id FROM cine.ventas v CROSS JOIN LATERAL jsonb_array_elements_text(v.snapshot_json->'asientos') a WHERE v.solicitud LIKE 'seed-%';

-- Ocupación realista de las próximas funciones: llena, media y libre.
-- Tres primeras fechas de cada película/sala, siempre relativas al BAT.
-- En cada jornada, dos de cuatro horarios tienen ventas; los demás quedan libres.
-- Compras de hasta cuatro entradas repartidas entre los clientes de prueba.
WITH fechas AS (
 SELECT f.*,s.precio,s.descuento,s.tipo_sala_id,d.plano_json,
   dense_rank() OVER(PARTITION BY f.sala_id,f.pelicula_id ORDER BY (f.inicio_utc AT TIME ZONE 'America/La_Paz')::date) AS dia,
   row_number() OVER(PARTITION BY f.sala_id,(f.inicio_utc AT TIME ZONE 'America/La_Paz')::date ORDER BY f.inicio_utc,f.id) AS turno
 FROM cine.funciones f JOIN cine.salas s ON s.id=f.sala_id JOIN cine.disenos d ON d.id=s.diseno_id
 WHERE f.inicio_utc > CURRENT_TIMESTAMP
), clientes AS (
 SELECT u.*,row_number() OVER(ORDER BY u.id)-1 AS posicion,count(*) OVER() AS cantidad_clientes
 FROM cine.usuarios u WHERE u.activo AND u.email <> 'cliente@cliente.com'
 AND EXISTS(SELECT 1 FROM cine.usuarios_roles ur JOIN cine.roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND r.name='Cliente')
), asientos AS (
 SELECT f.*,a.asiento,a.posicion,
   (a.posicion-1)/4 AS grupo
 FROM fechas f CROSS JOIN LATERAL (
   SELECT asiento,row_number() OVER(ORDER BY regexp_replace(asiento,'[0-9]','','g'),substring(asiento from '[0-9]+')::int) AS posicion
   FROM jsonb_array_elements_text(f.plano_json->'asientos') a(asiento)
 ) a
 WHERE f.dia<=3 AND f.turno IN(1,2)
   AND a.posicion <= CASE WHEN f.turno=1 THEN jsonb_array_length(f.plano_json->'asientos') ELSE jsonb_array_length(f.plano_json->'asientos')/2 END
   AND NOT EXISTS(SELECT 1 FROM cine.butacas_vendidas b WHERE b.funcion_id=f.id AND b.asiento=a.asiento)
), compras AS (
 SELECT id,sala_id,pelicula_id,experiencia_id,tipo_sala_id,inicio_utc,grupo,
   round(precio*(100-descuento)/100,2) AS precio,
   jsonb_agg(asiento ORDER BY posicion) AS asientos,count(*)::int AS cantidad
 FROM asientos GROUP BY id,sala_id,pelicula_id,experiencia_id,tipo_sala_id,inicio_utc,grupo,precio,descuento
)
SELECT md5('ocupacion:'||c.id||':'||c.grupo)::uuid,'F-OCUP-'||upper(substr(md5(c.id||':'||c.grupo),1,16)),
 upper(substr(md5('ingreso:'||c.id||':'||c.grupo),1,12)),u.id,NULL,c.id,'ocupacion:'||c.id||':'||c.grupo,c.precio*c.cantidad,c.cantidad,
 CASE WHEN c.grupo%2=0 THEN 'Pago QR' ELSE 'Tarjeta de débito' END,CURRENT_TIMESTAMP-make_interval(hours=>1+(c.grupo%36)::int),
 jsonb_build_object('solicitud','ocupacion:'||c.id||':'||c.grupo,'peliculaId',p.id,'pelicula',p.titulo,'numeroSala',c.sala_id,
 'tipoSala',c.tipo_sala_id,'tipoExperiencia',c.experiencia_id,'horario',to_char(c.inicio_utc AT TIME ZONE 'America/La_Paz','HH24:MI'),
 'ticketsMayores',c.cantidad,'ticketsMenores',0,'asientos',c.asientos,'cliente',u.nombre||' '||u.apellido,
 'documentoCliente',u.ci,'emailUsuario',u.email,'asientosMayoresPorCategoria',jsonb_build_object('0',c.cantidad),
 'preciosMayoresPorCategoria',jsonb_build_object('0',c.precio))
FROM compras c JOIN cine.peliculas p ON p.id=c.pelicula_id
JOIN clientes u ON u.posicion=(c.sala_id+c.grupo)%u.cantidad_clientes;

 SELECT v.funcion_id,a,v.id FROM cine.ventas v CROSS JOIN LATERAL jsonb_array_elements_text(v.snapshot_json->'asientos') a
 WHERE v.solicitud LIKE 'ocupacion:%';

-- Los snapshots históricos corresponden a las mismas películas, salas y butacas.
UPDATE cine.ventas v SET snapshot_json=v.snapshot_json || jsonb_build_object(
 'peliculaId',p.id,'pelicula',p.titulo,'fechaFuncion',to_char(f.inicio_utc AT TIME ZONE 'America/La_Paz','YYYY-MM-DD"T"HH24:MI:SS'),
 'generos',coalesce((SELECT jsonb_agg(g.nombre ORDER BY g.nombre) FROM cine.peliculas_generos pg JOIN cine.generos g ON g.id=pg.genero_id WHERE pg.pelicula_id=p.id),'[]'),
 'asientos',(SELECT jsonb_agg(b.asiento ORDER BY b.asiento) FROM cine.butacas_vendidas b WHERE b.venta_id=v.id),
 'tipoSala',s.tipo_sala_id,'tipoSalaNombre',ts.nombre,'experienciaNombre',e.nombre)
 FROM cine.funciones f JOIN cine.peliculas p ON p.id=f.pelicula_id JOIN cine.salas s ON s.id=f.sala_id JOIN cine.tipos_sala ts ON ts.id=s.tipo_sala_id JOIN cine.experiencias e ON e.id=f.experiencia_id WHERE f.id=v.funcion_id;

-- Confitería: una compra realista por día y categoría para poblar las tendencias.
SELECT md5('seed-pedido:'||dia||':'||c.id)::uuid,'P-SEED-'||dia||'-'||c.id,md5('token:'||dia||':'||c.id)||substr(md5(c.id::text),1,16),'seed-pedido:'||dia||':'||c.id,
 'CF-SEED-'||dia||'-'||c.id,u.id,'',u.nombre||' '||u.apellido,'Retirado',CASE WHEN c.id%2=0 THEN 'Pago QR' ELSE 'Efectivo' END,c.precio*(1+(dia+c.id)%3),
 CURRENT_TIMESTAMP-make_interval(days=>dia)-interval '2 hours',CURRENT_TIMESTAMP-make_interval(days=>dia),w.usuario_id
FROM generate_series(0,29) dia CROSS JOIN cine.combos c
CROSS JOIN (SELECT id,nombre,apellido FROM cine.usuarios WHERE email='cliente@cliente.com') u
CROSS JOIN (SELECT usuario_id FROM cine.trabajadores ORDER BY id LIMIT 1) w WHERE c.publicado AND (dia+c.id)%4=0;
SELECT 55+row_number() OVER(ORDER BY p.id,c.id),p.id,c.id,c.nombre,cat.nombre,1+(split_part(p.solicitud,':',2)::int+c.id)%3,c.precio
FROM cine.pedidos p JOIN cine.combos c ON c.id=split_part(p.solicitud,':',3)::int JOIN cine.categorias cat ON cat.id=c.categoria_id WHERE p.solicitud LIKE 'seed-pedido:%';

-- Reajustar secuencias despues de los IDs explicitos del seed.
DO $$ DECLARE tabla text; secuencia text; siguiente bigint; BEGIN
 FOREACH tabla IN ARRAY ARRAY['categorias','combos','disenos','distribuidoras','experiencias','generos','peliculas','salas','tipos_sala','trabajadores','banners','estrenos','pedido_lineas'] LOOP
  secuencia := pg_get_serial_sequence('cine.'||tabla,'id');
  EXECUTE format('SELECT coalesce(max(id),0)+1 FROM cine.%I',tabla) INTO siguiente;
  PERFORM setval(secuencia,siguiente,false);
 END LOOP;
END $$;
-- La API del servidor es el unico acceso a los datos de negocio.
REVOKE ALL ON SCHEMA cine FROM PUBLIC;
DO $$ DECLARE rol text; BEGIN
 FOREACH rol IN ARRAY ARRAY['anon','authenticated'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=rol) THEN
   EXECUTE format('REVOKE ALL ON SCHEMA cine FROM %I',rol);
   EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA cine FROM %I',rol);
   EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA cine FROM %I',rol);
  END IF;
 END LOOP;
END $$;
COMMIT;
